// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, getLinksSearch, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, headers, "Skyramp CaseProbe Collection");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Skyramp CaseProbe Collection");
    expect(getResponseValue(collectionsPostResponse, "response.isPublic"), 'isPublic').toBe(false);
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionId = getResponseValue(collectionsPostResponse, "response.id");

    const linksPostResponse = await createLink(
        client,
        headers,
        collectionId,
        "Skyramp CaseProbe GitHub Doc",
        "https://example.com/skyramp-caseprobe",
        "caseprobe description",
        []
    );

    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Skyramp CaseProbe GitHub Doc");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/skyramp-caseprobe");
    expect(getResponseValue(linksPostResponse, "response.description"), 'description').toBe("caseprobe description");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(collectionId);
    expect(getResponseValue(linksPostResponse, "response.tags").length, 'tags length').toBe(0);
    expect(getResponseValue(linksPostResponse, "response.tags.0"), 'tags.0').toBeNull();
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const probeLinkId = getResponseValue(linksPostResponse, "response.id");

    // An all-lowercase ?q must still find the mixed-case link: every other search path in
    // this application sets Prisma's `mode: "insensitive"` on name/url/description when the
    // datasource is PostgreSQL (searchLinks.ts:162, getLinks.ts:27).
    const searchGetResponse = await getLinksSearch(client, headers, {"q": ["caseprobe github"]});
    expect(searchGetResponse.statusCode, 'status code').toBe(200);
    const caseMatches = getResponseValue(searchGetResponse, "response");
    expect(Array.isArray(caseMatches), 'response is an array').toBe(true);
    expect(getResponseValue(searchGetResponse, "error"), 'error carries no value').toBeNull();
    expect(caseMatches.map((link: any) => link.id), 'lowercase q finds the mixed-case link').toContain(probeLinkId);
    const caseProbeMatch = caseMatches.find((link: any) => link.id === probeLinkId);
    expect(caseProbeMatch?.name, 'matched name').toBe("Skyramp CaseProbe GitHub Doc");
    expect(caseProbeMatch?.url, 'matched url').toBe("https://example.com/skyramp-caseprobe");
    expect(caseProbeMatch?.description, 'matched description').toBe("caseprobe description");
    expect(caseProbeMatch?.collectionId, 'matched collectionId').toBe(collectionId);

    const linksLinksDeleteResponse = await deleteLink(client, headers, probeLinkId);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted id').toBe(probeLinkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'deleted name').toBe("Skyramp CaseProbe GitHub Doc");

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collectionId);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted id').toBe(collectionId);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.name"), 'deleted name').toBe("Skyramp CaseProbe Collection");
});
